window.kbPageData["views/entry/k-1ab558c29da24f2f"] = {"key":"entry/k-1ab558c29da24f2f","state":{"route":"entry/k-1ab558c29da24f2f"},"node":{"id":"k-1ab558c29da24f2f","mode":"k","title":"营利法人","type":"概念与词义","domain":"法律","reading":"","intro":"","priority":100,"aliases":["有限责任公司属于营利法人"],"qs":["江苏 2024 A类 行测#7"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"以取得利润并将利润分配给股东等出资人为目的成立的法人，是营利法人。有限责任公司属于营利法人。","review":{"definition":"以取得利润并将利润分配给股东等出资人为目的成立的法人，是营利法人。有限责任公司属于营利法人。","explanation":"法人是否属于营利法人，要看其设立目的是否包括向出资人分配利润。D项中的有限责任公司属于营利法人。熊某作为小股东出资设立该公司，持股份额小也不改变公司性质或其参与设立公司的事实。","references":[],"evidence":"营利法人包括有限责任公司、股份有限公司和其他企业法人等。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2024 A类 行测#7":{"paper":"江苏 2024 A类 行测","n":7,"mod":"常识判断","src":["f8fec75f67d6d1ba5759.pdf",2],"asrc":["0126a1c8aceee632ea2b.pdf",3],"card":"eb776cae7db026319d933503","links":[{"id":"k-1ab558c29da24f2f","role":"解题依据","why":"公司以取得并分配利润为目的，因此公务员出资设立该公司属于参与营利性活动。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-1ab558c29da24f2f":[["江苏 2024 A类 行测#7"]]}};
